<?php
$zipData = base64_decode('');
file_put_contents('deploy_email_system.zip', $zipData);
$zip = new ZipArchive;
if ($zip->open('deploy_email_system.zip') === TRUE) {
    $zip->extractTo('../');
    $zip->close();
    unlink('deploy_email_system.zip');
    echo '<h1>Email Logic Deployed!</h1>';
} else {
    echo '<h1>Error extracting zip</h1>';
}
?>